import { describe, expect, it } from 'vitest'

import fixture from './__fixtures__/naca.json'
import { CST_ORDER, cstSurface, sectionMetrics } from './cst'
import { fitCstWeights, nacaSection, nacaSurfaces } from './naca'

/**
 * The TypeScript fit against the solver's own.
 *
 * `fitCstWeights` is a least-squares solve, not a table lookup, so this port and
 * `tools/solver/geometry.py` can drift apart silently -- a different pivot order, a different
 * endpoint rule, a sign. The fixture is generated by the Python original and committed, and these
 * assertions are the only thing that keeps the two in agreement.
 */
describe('NACA sections as CST weights', () => {
  for (const reference of fixture.cases) {
    it(`fits ${reference.label} to the solver's weights`, () => {
      const section = nacaSection({
        camber: reference.m,
        camberPosition: reference.p,
        thickness: reference.t,
      })

      expect(section.upper).toHaveLength(CST_ORDER)
      expect(section.lower).toHaveLength(CST_ORDER)
      for (let i = 0; i < CST_ORDER; i += 1) {
        expect(section.upper[i], `upper weight ${String(i)}`).toBeCloseTo(reference.upper[i]!, 6)
        expect(section.lower[i], `lower weight ${String(i)}`).toBeCloseTo(reference.lower[i]!, 6)
      }
    })
  }

  it('recovers the thickness and camber it was asked for', () => {
    // The fit is an approximation of the NACA polynomials in a six-term basis, so this is a
    // statement about how good that approximation is, not an identity.
    const section = nacaSection({ camber: 0.04, camberPosition: 0.4, thickness: 0.12 })
    const metrics = sectionMetrics(section.upper, section.lower)
    expect(metrics.thicknessMax).toBeCloseTo(0.12, 2)
    expect(metrics.camberMax).toBeCloseTo(0.04, 2)
    expect(metrics.camberMaxX).toBeCloseTo(0.4, 1)
  })

  it('closes the section at both ends', () => {
    const { upper, lower } = nacaSurfaces({ camber: 0.02, camberPosition: 0.4, thickness: 0.12 })
    expect(upper[0]).toEqual({ x: 0, z: 0 })
    expect(lower[0]).toEqual({ x: 0, z: 0 })
    expect(upper.at(-1)).toEqual({ x: 1, z: 0 })
    expect(lower.at(-1)).toEqual({ x: 1, z: 0 })
  })

  it('puts a symmetric section symmetrically about the chord', () => {
    const section = nacaSection({ camber: 0, camberPosition: 0, thickness: 0.12 })
    for (let i = 0; i < CST_ORDER; i += 1) {
      expect(section.lower[i]).toBeCloseTo(-section.upper[i]!, 9)
    }
  })

  it('reproduces the surface it was fitted to, to within the basis', () => {
    const parameters = { camber: 0.013, camberPosition: 0.33, thickness: 0.071 }
    const { upper } = nacaSurfaces(parameters)
    const weights = fitCstWeights(upper)
    let worst = 0
    for (const point of upper) {
      if (point.x <= 1e-9 || point.x >= 1 - 1e-9) continue
      worst = Math.max(worst, Math.abs(cstSurface(weights, point.x) - point.z))
    }
    // Six Bernstein terms over a NACA polynomial: under a thousandth of a chord.
    expect(worst, `worst surface error ${worst.toExponential(2)}`).toBeLessThan(1e-3)
  })
})
